    while (scanf("%63s", buf) == 1) {
        int valid = 1;
        int i = 0;
        if (buf[0] == '-' || buf[0] == '+') {
            i = 1;
        }
        if (buf[i] == 0) {
            valid = 0;
        }
        for (; buf[i]; i++) {
