int main(void) {
    char tok[128];
    int verbose = 0;
    int count = 0;
    int total = 0;
    char lastMode[16] = "QUIET";
    while (scanf("%127s", tok) == 1) {
        total++;
        if (strcmp(tok, "-v") == 0) {
            verbose = 1;
            strcpy(lastMode, "VERBOSE");
        } else if (strcmp(tok, "-q") == 0) {
            verbose = 0;
            strcpy(lastMode, "QUIET");
        } else if (strcmp(tok, "-n") == 0) {
            if (scanf("%127s", tok) == 1) {
                count = atoi(tok);
                total++;
            }
        }
    }
    printf("%s\n%d\n%d\n", lastMode, count, total);
    return 0;
}

