int main(void) {
    char tokens[32][80];
    int n = 0;
    while (n < 32 && scanf("%79s", tokens[n]) == 1) {
        n++;
    }
    if (n == 0) {
        return 1;
    }
    char query[80];
    strcpy(query, tokens[n - 1]);
    int m = n - 1;
    char found[80] = "NOTFOUND";
    int got = 0;
    for (int i = 0; i < m; i++) {
        char tmp[80];
        strcpy(tmp, tokens[i]);
        char *k = strtok(tmp, "=");
        char *v = strtok(NULL, "=");
        if (k && v && strcmp(k, query) == 0) {
            strcpy(found, v);
            got = 1;
        }
    }
    printf("%s\n", found);
    return 0;
}

#include <stdio.h>
#include <string.h>

int main(void) {
    char tok[128];
    char mode[16] = "QUIET";
    int count = 0;
    while (scanf("%127s", tok) == 1) {
        if (strcmp(tok, "--verbose") == 0) {
            strcpy(mode, "VERBOSE");
        } else if (strcmp(tok, "--quiet") == 0) {
            strcpy(mode, "QUIET");
        } else if (strstr(tok, "--count=") == tok) {
            const char *p = tok + 8;
            int v = 0;
            int sign = 1;
            if (*p == '-') {
                sign = -1;
                p++;
            }
            while (*p >= '0' && *p <= '9') {
                v = v * 10 + (*p - '0');
                p++;
            }
            count = sign * v;
        }
    }
    printf("%s\n%d\n", mode, count);
    return 0;
}

