int main(void) {
    char toks[64][32];
    int n = 0;
    while (n < 64 && scanf("%31s", toks[n]) == 1) {
        n++;
    }
    long vals[64];
    int vn = 0;
    char ops[64];
    int on = 0;
    for (int i = 0; i < n; i++) {
        if (strcmp(toks[i], "+") == 0 || strcmp(toks[i], "-") == 0) {
            ops[on++] = toks[i][0];
        } else if (strcmp(toks[i], "*") == 0) {
            if (i + 1 < n) {
                long left = vals[vn - 1];
                long right = (long)atoi(toks[i + 1]);
                vals[vn - 1] = left * right;
                i++;
            }
        } else {
            vals[vn++] = (long)atoi(toks[i]);
        }
    }
    long result = vn > 0 ? vals[0] : 0;
    for (int i = 0; i < on && i + 1 < vn; i++) {
        if (ops[i] == '+') {
            result += vals[i + 1];
        } else if (ops[i] == '-') {
            result -= vals[i + 1];
        }
    }
    printf("%ld\n", result);
    return 0;
}

#include <stdio.h>
