int main(void) {
    char toks[40][80];
    int n = 0;
    while (n < 40 && scanf("%79s", toks[n]) == 1) {
        n++;
    }
    if (n == 0) {
        return 1;
    }
    char cmd[80];
    strcpy(cmd, toks[0]);
    int values[40];
    int vn = 0;
    int nValue = 0;
    for (int i = 1; i < n; i++) {
        if (strcmp(toks[i], "-n") == 0 && i + 1 < n) {
            nValue = atoi(toks[i + 1]);
            i++;
        } else {
            values[vn++] = atoi(toks[i]);
        }
    }
    long result;
    if (strcmp(cmd, "add") == 0) {
        result = 0;
        for (int i = 0; i < vn; i++) {
            result += values[i];
        }
    } else if (strcmp(cmd, "sub") == 0) {
        result = vn > 0 ? values[0] : 0;
        for (int i = 1; i < vn; i++) {
            result -= values[i];
        }
    } else if (strcmp(cmd, "mul") == 0) {
        result = vn > 0 ? 1 : 0;
        for (int i = 0; i < vn; i++) {
            result *= values[i];
        }
    } else {
        result = 0;
    }
    printf("%ld\n", result);
    return 0;
}
